/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-command {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
}

:where([data-moru-registry]) .ui-command-backdrop {
  position: fixed;
  inset: 0;
  z-index: 95;
  background: #00000066;
  transition: opacity var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-command {
  position: fixed;
  z-index: 96;
  top: 15vh;
  left: 50%;
  translate: -50% 0;
  width: min(520px, calc(100vw - 24px));
  max-height: calc(85dvh - 24px);
  overflow-y: auto;
  overscroll-behavior: contain;
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  outline: none;
  transition:
    opacity var(--ui-duration, 160ms),
    transform var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-command-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--ui-control-gap, 8px);
  padding: var(--ui-control-padding-x-md, 12px) calc(var(--ui-space, 4px) * 4);
}
:where([data-moru-registry]) .ui-command-title {
  margin: 0;
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-command-close {
  display: inline-flex;
  flex: none;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  padding: 4px;
  border: 0;
  border-radius: max(2px, calc(var(--ui-radius, 6px) - 3px));
  background: transparent;
  color: var(--ui-muted, #6e6e6b);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-command-close:hover {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-command-search {
  display: flex;
  align-items: center;
  gap: var(--ui-control-gap, 8px);
  padding: 0 calc(var(--ui-space, 4px) * 3);
  border-block: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  margin: 0 calc(var(--ui-space, 4px) * 4) calc(var(--ui-space, 4px) * 2);
  border: var(--ui-border-width, 1px) solid transparent;
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-input-bg, #f0f0ed);
}
:where([data-moru-registry]) .ui-command-search > svg {
  flex: none;
  color: var(--ui-muted, #6e6e6b);
}

:where([data-moru-registry]) .ui-command-input {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  min-height: max(
    var(--ui-control-height-md, 40px),
    calc(
      var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45) +
        var(--ui-space, 4px) * 2
    )
  );
  padding: var(--ui-space, 4px) 0;
  border: 0;
  background: transparent;
  color: inherit;
  outline: none;
  font: inherit;
  font-size: var(--ui-type-label-size, 14px);
  line-height: var(--ui-type-label-line-height, 1.45);
}
:where([data-moru-registry]) .ui-command-input::placeholder {
  color: var(--ui-muted, #6e6e6b);
}
:where([data-moru-registry]) .ui-command-results {
  max-height: min(320px, 45dvh);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: calc(var(--ui-space, 4px) * 2);
}
:where([data-moru-registry]) .ui-command-results:empty {
  padding: 0;
}
:where([data-moru-registry]) .ui-command-group-label {
  padding: calc(var(--ui-space, 4px) * 3) var(--ui-control-padding-x-md, 12px)
    calc(var(--ui-space, 4px) * 2);
  color: var(--ui-muted, #6e6e6b);
  font-size: max(10px, calc(var(--ui-type-caption-size, 12px) - 1px));
  font-weight: var(--ui-type-label-weight, 550);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-command-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  box-sizing: border-box;
  gap: 2px;
  width: 100%;
  min-height: max(36px, var(--ui-control-height-md, 40px));
  padding: calc(var(--ui-space, 4px) * 2) var(--ui-control-padding-x-md, 12px);
  border: 0;
  border-radius: max(2px, calc(var(--ui-radius, 6px) - 3px));
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  text-align: start;
  overflow-wrap: anywhere;
  cursor: pointer;
}
:where([data-moru-registry]) .ui-command-item[data-highlighted] {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-command-item:disabled {
  color: var(--ui-disabled-text, #a1a1aa);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-command-item-description {
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 400);
}
:where([data-moru-registry]) .ui-command-hint,
:where([data-moru-registry]) .ui-command-empty {
  margin: 0;
  padding: calc(var(--ui-space, 4px) * 3) calc(var(--ui-space, 4px) * 4);
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-command-hint {
  border-top: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
}

:where([data-moru-registry]) .ui-command-close:focus-visible,
:where([data-moru-registry]) .ui-command-item:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-command-item:focus-visible {
  outline-offset: -3px;
}
:where([data-moru-registry]) .ui-command[data-starting-style],
:where([data-moru-registry]) .ui-command[data-ending-style] {
  opacity: 0;
  transform: translateY(-4px);
}
:where([data-moru-registry]) .ui-command-backdrop[data-starting-style],
:where([data-moru-registry]) .ui-command-backdrop[data-ending-style] {
  opacity: 0;
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-command-input {
    min-height: max(
      44px,
      var(--ui-control-height-md, 40px),
      calc(
        max(16px, var(--ui-type-label-size, 14px)) * var(--ui-type-label-line-height, 1.45) +
          var(--ui-space, 4px) * 2
      )
    );
    font-size: max(16px, var(--ui-type-label-size, 14px));
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-command,
  :where([data-moru-registry]) .ui-command-backdrop {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useId, useRef, useState, type KeyboardEvent, type ReactElement } from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { cn } from './_lib/cn'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './advanced-controls-shared.css'
import './command.css'

export interface CommandItem {
  id: string
  label: string
  description?: string
  keywords?: string[]
  group?: string
  disabled?: boolean
  onSelect: () => void
}

export interface CommandProps {
  items: CommandItem[]
  trigger?: ReactElement
  open?: boolean
  onOpenChange?: (open: boolean) => void
  title?: string
  placeholder?: string
  className?: string
}

export function Command({
  items,
  trigger,
  open,
  onOpenChange,
  title: titleProp,
  placeholder: placeholderProp,
  className,
}: CommandProps) {
  const { t } = useI18n()
  const title = titleProp ?? t('빠른 작업')
  const placeholder = placeholderProp ?? t('이름이나 작업을 검색하세요')

  const id = useId()
  const inputRef = useRef<HTMLInputElement>(null)
  const optionRefs = useRef(new Map<string, HTMLButtonElement>())
  const portalContainer = useThemePortalContainer()
  const [internalOpen, setInternalOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [activeId, setActiveId] = useState<string | null>(null)
  const isOpen = open ?? internalOpen
  const normalizedQuery = query.trim().toLocaleLowerCase()
  const results = items.filter((item) =>
    `${item.label} ${item.description ?? ''} ${(item.keywords ?? []).join(' ')}`
      .toLocaleLowerCase()
      .includes(normalizedQuery),
  )
  const groups = new Map<string, CommandItem[]>()
  for (const item of results) {
    const name = item.group ?? ''
    const group = groups.get(name) ?? []
    group.push(item)
    groups.set(name, group)
  }
  const enabled = [...groups.values()].flat().filter((item) => !item.disabled)
  const active = enabled.find((item) => item.id === activeId) ?? enabled[0]
  const optionIndices = new Map(items.map((item, index) => [item.id, index]))
  const optionId = (item: CommandItem) => `${id}-option-${optionIndices.get(item.id)}`
  const changeOpen = (nextOpen: boolean) => {
    if (open === undefined) setInternalOpen(nextOpen)
    if (!nextOpen) {
      setQuery('')
      setActiveId(null)
    }
    onOpenChange?.(nextOpen)
  }
  const selectItem = (item: CommandItem) => {
    if (item.disabled) return
    changeOpen(false)
    item.onSelect()
  }
  const highlight = (item: CommandItem | undefined) => {
    if (!item) return
    setActiveId(item.id)
    optionRefs.current.get(item.id)?.scrollIntoView({ block: 'nearest' })
  }
  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing) return
    const index = enabled.findIndex((item) => item.id === active?.id)
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      if (enabled.length)
        highlight(
          enabled[(index + (event.key === 'ArrowDown' ? 1 : -1) + enabled.length) % enabled.length],
        )
    } else if (event.key === 'Home' || event.key === 'End') {
      if (event.ctrlKey || event.metaKey) return
      event.preventDefault()
      highlight(event.key === 'Home' ? enabled[0] : enabled.at(-1))
    } else if (event.key === 'Enter' && active) {
      event.preventDefault()
      selectItem(active)
    }
  }
  return (
    <BaseDialog.Root
      open={isOpen}
      onOpenChange={changeOpen}
      onOpenChangeComplete={(nextOpen) => {
        if (!nextOpen) {
          setQuery('')
          setActiveId(null)
        }
      }}
    >
      {trigger && <BaseDialog.Trigger render={trigger} />}
      <OverlayPortal portal={BaseDialog.Portal} kind="command" container={portalContainer}>
        <BaseDialog.Backdrop className="ui-command-backdrop" />
        <BaseDialog.Popup className={cn('ui-command', className)} initialFocus={inputRef}>
          <div className="ui-command-heading">
            <BaseDialog.Title className="ui-command-title">{title}</BaseDialog.Title>
            <BaseDialog.Close className="ui-command-close" aria-label={t('빠른 작업 닫기')}>
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                <path
                  d="m4 4 8 8m0-8-8 8"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </svg>
            </BaseDialog.Close>
          </div>
          <div className="ui-command-search ui-field-focus">
            <svg width="18" height="18" viewBox="0 0 20 20" fill="none" aria-hidden="true">
              <circle cx="8.5" cy="8.5" r="5.5" stroke="currentColor" strokeWidth="1.5" />
              <path d="m13 13 4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
            <input
              ref={inputRef}
              className="ui-command-input"
              role="combobox"
              aria-label={placeholder}
              aria-autocomplete="list"
              aria-expanded="true"
              aria-controls={`${id}-list`}
              aria-activedescendant={active ? optionId(active) : undefined}
              value={query}
              placeholder={placeholder}
              autoComplete="off"
              onChange={(event) => {
                setQuery(event.target.value)
                setActiveId(null)
              }}
              onKeyDown={handleKeyDown}
            />
          </div>
          <div
            className="ui-command-results"
            id={`${id}-list`}
            role="listbox"
            aria-label={t('{v0} 검색 결과', { v0: title })}
          >
            {[...groups].map(([name, group], groupIndex) => (
              <div
                key={name}
                role="group"
                aria-labelledby={name ? `${id}-group-${groupIndex}` : undefined}
              >
                {name && (
                  <div className="ui-command-group-label" id={`${id}-group-${groupIndex}`}>
                    {name}
                  </div>
                )}
                {group.map((item) => (
                  <button
                    key={item.id}
                    ref={(element) => {
                      if (element) optionRefs.current.set(item.id, element)
                      else optionRefs.current.delete(item.id)
                    }}
                    type="button"
                    role="option"
                    tabIndex={-1}
                    id={optionId(item)}
                    aria-label={item.label}
                    aria-describedby={
                      item.description ? `${optionId(item)}-description` : undefined
                    }
                    aria-selected={item.id === active?.id}
                    aria-disabled={item.disabled || undefined}
                    data-highlighted={item.id === active?.id || undefined}
                    disabled={item.disabled}
                    className="ui-command-item"
                    onPointerMove={() => {
                      if (!item.disabled) setActiveId(item.id)
                    }}
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={() => selectItem(item)}
                  >
                    <span>{item.label}</span>
                    {item.description && (
                      <span
                        className="ui-command-item-description"
                        id={`${optionId(item)}-description`}
                      >
                        {item.description}
                      </span>
                    )}
                  </button>
                ))}
              </div>
            ))}
          </div>
          {results.length === 0 && (
            <p className="ui-command-empty">
              {t('검색 결과가 없습니다. 다른 검색어를 입력해보세요.')}
            </p>
          )}
          <span className="ui-advanced-sr-only" role="status" aria-live="polite" aria-atomic="true">
            {t('검색 결과 ')}
            {results.length}
            {t('개')}
          </span>
          <BaseDialog.Description className="ui-command-hint">
            {t('↑ ↓ 이동 · Enter 실행 · Esc 닫기')}
          </BaseDialog.Description>
        </BaseDialog.Popup>
      </OverlayPortal>
    </BaseDialog.Root>
  )
}
